package com.bank.isolation.bulkhead;

import java.util.concurrent.Semaphore;
import java.util.logging.Logger;

// Bounded concurrency: only N calls run at once; overflow is rejected fast.
public class Bulkhead {
    private static final Logger log = Logger.getLogger(Bulkhead.class.getName());
    private final String name;
    private final Semaphore permits;
    private int rejected = 0;

    public Bulkhead(String name, int maxConcurrentCalls) {
        this.name = name;
        this.permits = new Semaphore(maxConcurrentCalls);
    }

    // Try to acquire a slot; false means the compartment is full.
    public boolean tryEnter() {
        boolean ok = permits.tryAcquire();
        if (!ok) {
            rejected++;
            log.warning(() -> "BULKHEAD[" + name + "] full -> rejecting call (isolated)");
        }
        return ok;
    }

    public void leave() { permits.release(); }
    public int available() { return permits.availablePermits(); }
    public int getRejected() { return rejected; }
    public String getName() { return name; }
}
