package com.bank.isolation.breaker;

import java.util.logging.Logger;

// Temporal isolation: stop calling a clearly-broken dependency.
public class CircuitBreaker {
    private static final Logger log = Logger.getLogger(CircuitBreaker.class.getName());
    public enum State { CLOSED, OPEN }
    private final String name;
    private State state = State.CLOSED;
    private int failures = 0;
    private final int threshold;

    public CircuitBreaker(String name, int threshold) {
        this.name = name;
        this.threshold = threshold;
    }

    public boolean allow() { return state == State.CLOSED; }

    public void onSuccess() { failures = 0; state = State.CLOSED; }

    public void onFailure() {
        if (++failures >= threshold) {
            state = State.OPEN;
            log.severe(() -> "CIRCUIT[" + name + "] OPEN -> fail fast (temporal isolation)");
        }
    }

    public State getState() { return state; }
}
