package com.bank.isolation.downstream;

// Simulated dependency; can be made slow/failing to test isolation.
public class DownstreamService {
    private volatile boolean slow = false;
    public void setSlow(boolean slow) { this.slow = slow; }

    public String call(String op) {
        if (slow) {
            try { Thread.sleep(200); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            throw new RuntimeException(op + " timed out (dependency slow)");
        }
        return op + " ok";
    }
}
