package com.bank.isolation.service;

import com.bank.isolation.breaker.CircuitBreaker;
import com.bank.isolation.bulkhead.Bulkhead;
import com.bank.isolation.downstream.DownstreamService;
import java.util.logging.Logger;

// Each call type runs in its OWN bulkhead + breaker (spatial + temporal isolation).
public class IsolatedAccountService {
    private static final Logger log = Logger.getLogger(IsolatedAccountService.class.getName());

    private final DownstreamService downstream;
    private final Bulkhead balanceBh = new Bulkhead("balance", 50);
    private final Bulkhead transferBh = new Bulkhead("transfer", 30);
    private final Bulkhead statementBh = new Bulkhead("statement", 10);
    private final CircuitBreaker statementCb = new CircuitBreaker("statement", 5);

    public IsolatedAccountService(DownstreamService downstream) { this.downstream = downstream; }

    public boolean checkBalance(String accountId) {
        return runIsolated(balanceBh, null, "balance:" + accountId);
    }

    public boolean transfer(String from, String to) {
        return runIsolated(transferBh, null, "transfer:" + from + "->" + to);
    }

    public boolean generateStatement(String accountId) {
        return runIsolated(statementBh, statementCb, "statement:" + accountId);
    }

    // Exception handling + bulkhead + breaker in one controlled path.
    private boolean runIsolated(Bulkhead bulkhead, CircuitBreaker breaker, String op) {
        if (breaker != null && !breaker.allow()) {
            log.warning(() -> "SKIP " + op + " (circuit open)");
            return false; // fail fast, isolated in time
        }
        if (!bulkhead.tryEnter()) {
            return false; // isolated in space: compartment full
        }
        try {
            String result = downstream.call(op);
            if (breaker != null) breaker.onSuccess();
            log.fine(() -> "OK " + result + " [" + bulkhead.getName()
                    + " free=" + bulkhead.available() + "]");
            return true;
        } catch (RuntimeException ex) {
            if (breaker != null) breaker.onFailure();
            log.severe(() -> "FAIL " + op + ": " + ex.getMessage() + " (contained)");
            return false; // exception does NOT cross the boundary
        } finally {
            bulkhead.leave();
        }
    }

    public int statementRejected() { return statementBh.getRejected(); }
    public CircuitBreaker.State statementBreaker() { return statementCb.getState(); }
    public int balanceFree() { return balanceBh.available(); }
    public int transferFree() { return transferBh.available(); }
}
