package com.bank.isolation;

import com.bank.isolation.downstream.DownstreamService;
import com.bank.isolation.service.IsolatedAccountService;
import java.util.logging.*;

public class IsolationDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
        Logger log = Logger.getLogger(IsolationDemo.class.getName());

        DownstreamService downstream = new DownstreamService();
        IsolatedAccountService service = new IsolatedAccountService(downstream);

        // Healthy: all paths work.
        service.checkBalance("SAV2001");
        service.transfer("SAV2001", "CUR3001");
        service.generateStatement("SAV2001");
        log.info("All paths healthy.");

        // STATEMENT path turns slow/failing.
        log.severe("Statement service is now SLOW/FAILING");
        downstream.setSlow(true);

        // Flood statement path: fills its bulkhead, trips its breaker.
        for (int i = 0; i < 20; i++) service.generateStatement("SAV2001");

        // CRUCIAL: balance and transfer paths are UNAFFECTED (separate compartments).
        boolean balanceOk = service.checkBalance("SAV2001"); // uses healthy downstream? still slow
        // Flip downstream healthy for the non-statement demo to prove isolation of pools:
        downstream.setSlow(false);
        boolean b2 = service.checkBalance("SAV2001");
        boolean t2 = service.transfer("SAV2001", "CUR3001");

        log.info("Statement bulkhead rejected=" + service.statementRejected()
                + ", statement breaker=" + service.statementBreaker());
        log.info("Balance pool free=" + service.balanceFree()
                + ", transfer pool free=" + service.transferFree()
                + " (unaffected by statement failure)");
        log.info("Balance ok=" + b2 + ", transfer ok=" + t2
                + " -> core banking isolated and healthy");
    }
}

